import { NextResponse, NextRequest } from "next/server"
import { DeviceCommand } from "@/lib/types"
import { getFood } from "@/lib/feeding"
import { getWater } from "@/lib/refill"

export async function GET(req: NextRequest, context: { params: Promise<{ id: string }>}){
    const { id: deviceID } = await context.params
    let command: DeviceCommand

    if(deviceID == "FOOD"){
        command = await getFood(deviceID)
    } else {
        command = {
            command: "ERROR",
            reason: "UNKNOWN_DEVICE_ID"
        }
    }

    return NextResponse.json(command)
}   

export async function POST(req: NextRequest, context: { params: Promise<{ id: string }>}){
    const { id: deviceID } = await context.params
    const body = await req.json()
    let command: DeviceCommand

    if(deviceID == "WATER"){
        let waterLevel = Number(body.waterLevel)
        command = await getWater(deviceID, waterLevel)
    } else { 
        command = {
            command: "ERROR",
            reason: "UNKNOWN_DEVICE_ID"
        }
    }

    return NextResponse.json(command)
}
